  "abstract": "A thermal array occupancy sensor subtracts a stored background frame and adapts it during low activity.",
  "description": "A ceiling thermal array sensor stores a background frame at installation. During periods of low activity, the background frame is updated as a running average of recent frames. A pixel is marked occupied when its reading exceeds the background by a threshold derived from that pixel's noise.",
  "claims": [
    {
      "number": 1,
      "depends_on": null,
      "text": "A method of detecting occupancy, comprising: storing a background frame from a thermal array; updating the background frame during periods of low activity; and marking a pixel occupied when its reading exceeds the background frame by a threshold derived from a noise estimate of that pixel."
    },
    {
      "number": 2,
      "depends_on": 1,
      "text": "The method of claim 1, wherein low activity is determined from the variance of recent frames."
    }
  ]
}
